      d.style.cssText = 'position:fixed;left:50%;top:18%;transform:translateX(-50%);z-index:2147483647;background:#0d1419f2;color:#e8f6ff;border:1px solid #2b3a45;border-radius:12px;padding:11px 14px;font:600 13px system-ui;box-shadow:0 10px 30px #0009';
      document.body.appendChild(d);
